def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n < 4:
        return 'C' if n % 2 == 0 else 'D'
    mine = [h[0] for h in history]
    opp = [h[1] for h in history]
    op_c = opp.count('C')
    my_c = mine.count('C')
    last_opp = opp[-1]
    last_my = mine[-1]
    recent = list(zip(mine[-8:], opp[-8:]))
    opp_recent_d = sum(1 for _, o in recent if o == 'D')
    opp_recent_c = len(recent) - opp_recent_d
    my_recent_d = sum(1 for m, _ in recent if m == 'D')
    if opp_recent_d >= 6:
        return 'D'
    if opp_recent_c >= 7:
        return 'C'
    if n == 4:
        if opp.count('D') >= 2:
            return 'D'
        return 'C'
    if n < 12:
        if last_opp == 'D':
            return 'D'
        return 'C'
    coop_ratio = op_c / n
    if coop_ratio > 0.85:
        if last_opp == 'D' and opp_recent_d <= 1:
            return 'D'
        return 'C'
    if coop_ratio < 0.25:
        return 'D'
    if last_opp == 'D' and last_my == 'D':
        return 'C' if opp_recent_d <= 2 else 'D'
    if last_opp == 'D':
        return 'D'
    if coop_ratio > 0.6:
        return 'C'
    if last_my == 'D' and opp_recent_d >= 3:
        return 'D'
    if opp_recent_c >= 5 and coop_ratio > 0.4:
        return 'C'
    if coop_ratio > 0.5:
        return 'C'
    return 'D'
